1	//! What a component's own function body does with its props, read from the syntax alone (trail 405): which props it
2	//! reads, the JSX elements it writes with their attributes in source order, and whether it hands its props object on
3	//! whole. Facts only: what they mean for which props are relevant is the resolver's to decide, and nothing here is
4	//! emitted.
5	//!
6	//! The function is the one a mapping's declaration holds, through the wrapper calls the extractor unwraps (`memo`,
7	//! `forwardRef`, a factory's first argument). Elements built with `createElement` are not recorded.
8	//!
9	//! # Conservative by construction
10	//!
11	//! Names are resolved by `oxc_semantic`, which binds every reference to its symbol: a parameter, `var`, `let`,
12	//! function or class name, catch or loop binding of the same name is another symbol, and what is the component's is
13	//! decided by the symbol. Every reference to the props object (the first parameter and each rest binding taken from
14	//! it) is classified by the node around it, through TypeScript's `as`, `satisfies`, `!` and `<T>`; only three are
15	//! safe:
16	//!
17	//! - the object of a member read with a static or string-literal key (`props.x`, `props?.['x']`) that is not called
18	//!   (`props.f()` passes the object as `this`), written, deleted or destructured into: `x` is read;
19	//! - the initializer of an object destructuring (`const { a, b = 1, ...r } = props`) or the right side of a
20	//!   destructuring assignment: its static keys are read, and a rest binding is the props object again;
21	//! - a JSX spread attribute (`{...props}`): recorded as a spread, and the whole props object spread is handed on.
22	//!
23	//! Any other reference (a call argument, `new`, an attribute value, an object or array literal, a `return`, a
24	//! computed key, an assignment, `typeof`, a type query) hands the object on, so `reads` is complete only when
25	//! `handed_on` is false.
26	//!
27	//! A function or class the body binds and renders as a JSX tag, by symbol (`const Item = () => <li/>; return
28	//! <Item/>`), is a component of its own: its references to the props object still count, but its elements are the
29	//! file's ([`JsxUsage`]), not the parent's.
30	
31	use std::collections::VecDeque;
32	
33	use oxc_ast::AstKind;
34	use oxc_ast::ast::*;
35	use oxc_ast_visit::{Visit, walk};
36	use oxc_semantic::{AstNodes, Scoping, SemanticBuilder};
37	use oxc_span::GetSpan;
38	use oxc_syntax::node::NodeId;
39	use oxc_syntax::scope::ScopeFlags;
40	use oxc_syntax::symbol::SymbolId;
41	use rustc_hash::{FxHashMap, FxHashSet};
42	
43	use super::component::peel_expr;
44	use super::js_text;
45	use crate::types::collected::{
46	    BodyFacts, ComponentMapping, JsxAttributeFact, JsxElementFact, JsxTag, JsxUsage, JsxUsageAttribute, SpreadOf,
47	};
48	
49	/// Records on each mapping the facts of the function its declaration holds, and returns the file's other JSX elements:
50	/// those outside every function a mapping is given facts of (pages, stories, helpers, module-level JSX, class
51	/// components) and those of components nested in one. A mapping with no function of its own (a class, an alias of
52	/// another component, a declaration without a body) gets none. The semantic pass runs only for a file with at least
53	/// one such function.
54	pub(super) fn attach<'a>(program: &'a Program<'a>, mappings: &mut [ComponentMapping], jsx: bool) -> Vec<JsxUsage> {
55	    if mappings.is_empty() && !jsx {
56	        return Vec::new();
57	    }
58	    let mut finder = Finder {
59	        wanted: mappings.iter().map(|mapping| (mapping.span_start, mapping.span_end)).collect(),
60	        functions: FxHashMap::default(),
61	        owned: 0,
62	        usages: Vec::new(),
63	    };
64	    finder.visit_program(program);
65	    let Finder { functions, mut usages, .. } = finder;
66	    if functions.is_empty() {
67	        return usages;
68	    }
69	
70	    // The nodes are what a reference's parent is read from.
71	    let semantic = SemanticBuilder::new().with_build_nodes(true).build(program).semantic;
72	    let (scoping, nodes) = (semantic.scoping(), semantic.nodes());
73	    let mut found = FxHashMap::default();
74	    // Elements of nested components, each at the place in `usages` its component's declaration was reached.
75	    let mut nested: Vec<(usize, Vec<JsxUsage>)> = Vec::new();
76	    for node in nodes.iter() {
77	        let (span, function) = match node.kind() {
78	            AstKind::Function(function) => (function.span, ComponentFn::Function(function)),
79	            AstKind::ArrowFunctionExpression(arrow) => (arrow.span, ComponentFn::Arrow(arrow)),
80	            _ => continue,
81	        };
82	        let Some(holders) = functions.get(&(span.start, span.end)) else { continue };
83	        let (facts, usages_of_nested) = Reader::new(scoping, nodes).facts_of(&function);
84	        for &(key, _) in holders {
85	            found.entry(key).or_insert_with(|| facts.clone());
86	        }
87	        // Once per function, where the first mapping holding it was reached.
88	        if let Some(at) = holders.iter().map(|&(_, at)| at).min() {
89	            nested.push((at, usages_of_nested));
90	        }
91	    }
92	    nested.sort_by_key(|(at, _)| *at);
93	    for (at, inserted) in nested.into_iter().rev() {
94	        usages.splice(at..at, inserted);
95	    }
96	    for mapping in mappings {
97	        mapping.body = found.get(&(mapping.span_start, mapping.span_end)).cloned();
98	    }
99	    usages
100	}
101	
102	/// A component function, by the parts the facts are read from.
103	enum ComponentFn<'b, 'a> {
104	    Function(&'b Function<'a>),
105	    Arrow(&'b ArrowFunctionExpression<'a>),
106	}
107	
108	impl ComponentFn<'_, '_> {
109	    fn span(&self) -> oxc_span::Span {
110	        match self {
111	            Self::Function(function) => function.span,
112	            Self::Arrow(arrow) => arrow.span,
113	        }
114	    }
115	}
116	
117	/// The function an expression is, through parentheses, type assertions and the first argument of wrapper calls
118	/// (`memo(forwardRef((props, ref) => …))`).
119	fn unwrap<'b, 'a>(expr: &'b Expression<'a>) -> Option<ComponentFn<'b, 'a>> {
120	    match peel_expr(expr) {
121	        Expression::FunctionExpression(function) => Some(ComponentFn::Function(function)),
122	        Expression::ArrowFunctionExpression(arrow) => Some(ComponentFn::Arrow(arrow)),
123	        Expression::CallExpression(call) => unwrap(call.arguments.first()?.as_expression()?),
124	        _ => None,
125	    }
126	}
127	
128	/// A span as `(start, end)`.
129	type SpanKey = (u32, u32);
130	
131	/// A mapping's span that holds a component function, and where in the file's usages it was reached.
132	type Holder = (SpanKey, usize);
133	
134	/// Finds the nodes that start and end where a mapping does and the function each holds, and collects the JSX
135	/// elements outside all of those functions.
136	struct Finder {
137	    wanted: FxHashSet<SpanKey>,
138	    /// The span of each component function, to the mappings that hold it.
139	    functions: FxHashMap<SpanKey, Vec<Holder>>,
140	    /// How many component functions enclose the current node.
141	    owned: u32,
142	    usages: Vec<JsxUsage>,
143	}
144	
145	impl Finder {
146	    /// Notes the function a wanted node holds; `true` when the node is one, so its JSX is the component's.
147	    fn record(&mut self, span: oxc_span::Span, function: Option<ComponentFn<'_, '_>>) -> bool {
148	        let key = (span.start, span.end);
149	        let Some(function) = function.filter(|_| self.wanted.contains(&key)) else { return false };
150	        let function = function.span();
151	        let holders = self.functions.entry((function.start, function.end)).or_default();
152	        if !holders.iter().any(|(held, _)| *held == key) {
153	            holders.push((key, self.usages.len()));
154	        }
155	        true
156	    }
157	
158	    fn walk_owned(&mut self, owned: bool, walk: impl FnOnce(&mut Self)) {
159	        self.owned += u32::from(owned);
160	        walk(self);
161	        self.owned -= u32::from(owned);
162	    }
163	}
164	
165	impl<'a> Visit<'a> for Finder {
166	    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
167	        let owned = self.record(it.span, it.init.as_ref().and_then(unwrap));
168	        self.walk_owned(owned, |finder| walk::walk_variable_declarator(finder, it));
169	    }
170	
171	    fn visit_export_default_declaration(&mut self, it: &ExportDefaultDeclaration<'a>) {
172	        let owned = self.record(it.span, it.declaration.as_expression().and_then(unwrap));
173	        self.walk_owned(owned, |finder| walk::walk_export_default_declaration(finder, it));
174	    }
175	
176	    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
177	        let owned = self.record(it.span, Some(ComponentFn::Function(it)));
178	        self.walk_owned(owned, |finder| walk::walk_function(finder, it, flags));
179	    }
180	
181	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
182	        let owned = self.record(it.span, Some(ComponentFn::Arrow(it)));
183	        self.walk_owned(owned, |finder| walk::walk_arrow_function_expression(finder, it));
184	    }
185	
186	    fn visit_jsx_opening_element(&mut self, it: &JSXOpeningElement<'a>) {
187	        if self.owned == 0 {
188	            self.usages.push(usage_of(it));
189	        }
190	        walk::walk_jsx_opening_element(self, it);
191	    }
192	}
193	
194	fn usage_of(it: &JSXOpeningElement<'_>) -> JsxUsage {
195	    let attributes = it
196	        .attributes
197	        .iter()
198	        .map(|attribute| match attribute {
199	            JSXAttributeItem::Attribute(attribute) => JsxUsageAttribute::Named(attribute_name(&attribute.name)),
200	            JSXAttributeItem::SpreadAttribute(_) => JsxUsageAttribute::Spread,
201	        })
202	        .collect();
203	    JsxUsage { tag: tag_of(&it.name), attributes }
204	}
205	
206	/// Reads one component function against the file's semantic model.
207	struct Reader<'s, 'a> {
208	    scoping: &'s Scoping,
209	    nodes: &'s AstNodes<'a>,
210	    facts: BodyFacts,
211	    /// The props object's symbols: the first parameter, and each rest binding taken from it.
212	    whole: FxHashMap<SymbolId, SpreadOf>,
213	    /// The symbols still to classify the references of.
214	    queue: VecDeque<SymbolId>,
215	    /// The destructured locals that hold one prop's value unchanged: no default, never written.
216	    locals: FxHashMap<SymbolId, String>,
217	}
218	
219	impl<'s, 'a> Reader<'s, 'a> {
220	    fn new(scoping: &'s Scoping, nodes: &'s AstNodes<'a>) -> Self {
221	        Self {
222	            scoping,
223	            nodes,
224	            facts: BodyFacts::default(),
225	            whole: FxHashMap::default(),
226	            queue: VecDeque::new(),
227	            locals: FxHashMap::default(),
228	        }
229	    }
230	
231	    fn facts_of(mut self, function: &ComponentFn<'_, 'a>) -> (BodyFacts, Vec<JsxUsage>) {
232	        let params = match function {
233	            ComponentFn::Function(function) => &*function.params,
234	            ComponentFn::Arrow(arrow) => &*arrow.params,
235	        };
236	        if let Some(first) = params.items.first() {
237	            self.props_param(&first.pattern);
238	        }
239	        while let Some(symbol) = self.queue.pop_front() {
240	            for reference in self.scoping.get_resolved_references(symbol) {
241	                self.classify(reference.node_id());
242	            }
243	        }
244	        let mut elements = Elements {
245	            reader: &self,
246	            tags: FxHashSet::default(),
247	            nested: 0,
248	            elements: Vec::new(),
249	            nested_usages: Vec::new(),
250	        };
251	        // The parameters too: a default or a computed key can hold JSX (`{ icon = <Icon /> }`).
252	        match function {
253	            ComponentFn::Function(function) => {
254	                elements.tags = tag_symbols(self.scoping, |tags| {
255	                    tags.visit_formal_parameters(&function.params);
256	                    if let Some(body) = &function.body {
257	                        tags.visit_function_body(body);
258	                    }
259	                });
260	                elements.visit_formal_parameters(&function.params);
261	                if let Some(body) = &function.body {
262	                    elements.visit_function_body(body);
263	                }
264	            }
265	            ComponentFn::Arrow(arrow) => {
266	                elements.tags = tag_symbols(self.scoping, |tags| {
267	                    tags.visit_formal_parameters(&arrow.params);
268	                    tags.visit_arrow_function_body(&arrow.body);
269	                });
270	                elements.visit_formal_parameters(&arrow.params);
271	                elements.visit_arrow_function_body(&arrow.body);
272	            }
273	        }
274	        let (found, nested_usages) = (elements.elements, elements.nested_usages);
275	        self.facts.elements = found;
276	        (self.facts, nested_usages)
277	    }
278	
279	    fn props_param(&mut self, pattern: &BindingPattern<'_>) {
280	        match pattern {
281	            BindingPattern::BindingIdentifier(id) => {
282	                if let Some(symbol) = id.symbol_id.get() {
283	                    self.track(symbol, SpreadOf::Props);
284	                }
285	            }
286	            // `function C({ a } = {})`.
287	            BindingPattern::AssignmentPattern(assignment) => self.props_param(&assignment.left),
288	            BindingPattern::ObjectPattern(object) => self.destructure(object),
289	            // An array pattern reads indices of the props object, which says nothing about its keys.
290	            BindingPattern::ArrayPattern(_) => self.facts.handed_on = true,
291	        }
292	    }
293	
294	    fn track(&mut self, symbol: SymbolId, whole: SpreadOf) {
295	        if self.whole.insert(symbol, whole).is_none() {
296	            self.queue.push_back(symbol);
297	        }
298	    }
299	
300	    fn read(&mut self, prop: String) {
301	        if !self.facts.reads.contains(&prop) {
302	            self.facts.reads.push(prop);
303	        }
304	    }
305	
306	    /// An object pattern taken from the props object: each static key is read, a plain name bound to a key that is
307	    /// never written holds that prop, and a rest binding is the props object again.
308	    fn destructure(&mut self, object: &ObjectPattern<'_>) {
309	        for property in &object.properties {
310	            let Some(key) = property.key.static_name().map(|key| js_text::property_name(&key)) else {
311	                // `{ [k]: v }` reads a key the syntax does not name.
312	                self.facts.handed_on = true;
313	                continue;
314	            };
315	            if let BindingPattern::BindingIdentifier(id) = &property.value
316	                && let Some(symbol) = id.symbol_id.get()
317	                && !self.scoping.symbol_is_mutated(symbol)
318	                // `var a` or `function a` beside `{ a }` is the same symbol, given another value.
319	                && self.scoping.symbol_redeclarations(symbol).is_empty()
320	            {
321	                self.locals.insert(symbol, key.clone());
322	            }
323	            self.read(key);
324	        }
325	        if let Some(rest) = &object.rest {
326	            match &rest.argument {
327	                BindingPattern::BindingIdentifier(id) => {
328	                    self.facts.rests.push(id.name.to_string());
329	                    if let Some(symbol) = id.symbol_id.get() {
330	                        self.track(symbol, SpreadOf::Rest);
331	                    }
332	                }
333	                _ => self.facts.handed_on = true,
334	            }
335	        }
336	    }
337	
338	    /// The nearest ancestor of `node` that is not a TypeScript assertion or parentheses, and the span of the child
339	    /// of it the walk came from.
340	    fn through_wrappers(&self, node: NodeId) -> (NodeId, oxc_span::Span) {
341	        let (mut child, mut parent) = (self.nodes.kind(node).span(), self.nodes.parent_id(node));
342	        while matches!(
343	            self.nodes.kind(parent),
344	            AstKind::TSAsExpression(_)
345	                | AstKind::TSSatisfiesExpression(_)
346	                | AstKind::TSNonNullExpression(_)
347	                | AstKind::TSTypeAssertion(_)
348	                | AstKind::TSInstantiationExpression(_)
349	                | AstKind::ParenthesizedExpression(_)
350	        ) {
351	            child = self.nodes.kind(parent).span();
352	            parent = self.nodes.parent_id(parent);
353	        }
354	        (parent, child)
355	    }
356	
357	    /// Classifies one reference to the props object; any use not named here hands it on.
358	    fn classify(&mut self, reference: NodeId) {
359	        let (parent, child) = self.through_wrappers(reference);
360	        let read = match self.nodes.kind(parent) {
361	            AstKind::StaticMemberExpression(member) if member.object.span() == child => {
362	                Some(member.property.name.to_string())
363	            }
364	            AstKind::ComputedMemberExpression(member) if member.object.span() == child => match &member.expression {
365	                Expression::StringLiteral(key) => Some(js_text::lossy(key.value).into_owned()),
366	                _ => None,
367	            },
368	            AstKind::JSXMemberExpression(member) => Some(member.property.name.to_string()),
369	            AstKind::VariableDeclarator(declarator)
370	                if declarator.init.as_ref().is_some_and(|init| init.span() == child) =>
371	            {
372	                match &declarator.id {
373	                    BindingPattern::ObjectPattern(object) => self.destructure(object),
374	                    _ => self.facts.handed_on = true,
375	                }
376	                return;
377	            }
378	            AstKind::AssignmentExpression(assignment) if assignment.right.span() == child => {
379	                match &assignment.left {
380	                    AssignmentTarget::ObjectAssignmentTarget(object) if object.rest.is_none() => {
381	                        for property in &object.properties {
382	                            match property {
383	                                AssignmentTargetProperty::AssignmentTargetPropertyIdentifier(property) => {
384	                                    self.read(property.binding.name.to_string());
385	                                }
386	                                AssignmentTargetProperty::AssignmentTargetPropertyProperty(property) => {
387	                                    match property.name.static_name() {
388	                                        Some(key) => self.read(js_text::property_name(&key)),
389	                                        None => self.facts.handed_on = true,
390	                                    }
391	                                }
392	                            }
393	                        }
394	                    }
395	                    _ => self.facts.handed_on = true,
396	                }
397	                return;
398	            }
399	            AstKind::JSXSpreadAttribute(_) => {
400	                // Spreading the whole props object passes every prop on; a rest binding's spread is recorded only.
401	                if self.is_props(reference) {
402	                    self.facts.handed_on = true;
403	                }
404	                return;
405	            }
406	            _ => None,
407	        };
408	        let is_jsx_tag = matches!(self.nodes.kind(parent), AstKind::JSXMemberExpression(_));
409	        match read {
410	            Some(key) if is_jsx_tag || self.is_read(parent) => self.read(key),
411	            Some(_) | None => self.facts.handed_on = true,
412	        }
413	    }
414	
415	    /// Whether the reference at `node` is to the first parameter itself rather than a rest binding.
416	    fn is_props(&self, node: NodeId) -> bool {
417	        let AstKind::IdentifierReference(id) = self.nodes.kind(node) else { return false };
418	        self.symbol_of(id).and_then(|symbol| self.whole.get(&symbol)) == Some(&SpreadOf::Props)
419	    }
420	
421	    /// Whether a member expression is only read: not called with its object as `this`, written, deleted or
422	    /// destructured into.
423	    fn is_read(&self, member: NodeId) -> bool {
424	        let (parent, child) = self.through_wrappers(member);
425	        let (parent, child) = match self.nodes.kind(parent) {
426	            // `props?.x`: the chain is what is called, written or deleted (`delete props?.x`, `(props?.f)()`).
427	            AstKind::ChainExpression(_) => self.through_wrappers(parent),
428	            _ => (parent, child),
429	        };
430	        match self.nodes.kind(parent) {
431	            AstKind::CallExpression(call) => call.callee.span() != child,
432	            AstKind::TaggedTemplateExpression(tagged) => tagged.tag.span() != child,
433	            AstKind::AssignmentExpression(assignment) => assignment.left.span() != child,
434	            AstKind::UnaryExpression(unary) => unary.operator != UnaryOperator::Delete,
435	            AstKind::ForInStatement(each) => each.left.span() != child,
436	            AstKind::ForOfStatement(each) => each.left.span() != child,
437	            AstKind::UpdateExpression(_)
438	            | AstKind::ArrayAssignmentTarget(_)
439	            | AstKind::ObjectAssignmentTarget(_)
440	            | AstKind::AssignmentTargetRest(_)
441	            | AstKind::AssignmentTargetWithDefault(_)
442	            | AstKind::AssignmentTargetPropertyProperty(_) => false,
443	            _ => true,
444	        }
445	    }
446	
447	    fn symbol_of(&self, id: &IdentifierReference<'_>) -> Option<SymbolId> {
448	        id.reference_id.get().and_then(|reference| self.scoping.get_reference(reference).symbol_id())
449	    }
450	
451	    fn whole_expr(&self, expr: &Expression<'_>) -> Option<SpreadOf> {
452	        match peel_expr(expr) {
453	            Expression::Identifier(id) => self.symbol_of(id).and_then(|symbol| self.whole.get(&symbol).copied()),
454	            _ => None,
455	        }
456	    }
457	
458	    /// The prop an attribute's value is, when it is exactly one: an unchanged destructured name, `props.x`, `rest.x`.
459	    fn value_prop(&self, value: Option<&JSXAttributeValue<'_>>) -> Option<String> {
460	        let Some(JSXAttributeValue::ExpressionContainer(container)) = value else { return None };
461	        let (object, key) = match peel_expr(container.expression.as_expression()?) {
462	            Expression::Identifier(id) => {
463	                return self.symbol_of(id).and_then(|symbol| self.locals.get(&symbol).cloned());
464	            }
465	            Expression::StaticMemberExpression(member) => (&member.object, member.property.name.to_string()),
466	            Expression::ComputedMemberExpression(member) => match &member.expression {
467	                Expression::StringLiteral(key) => (&member.object, js_text::lossy(key.value).into_owned()),
468	                _ => return None,
469	            },
470	            Expression::ChainExpression(chain) => match &chain.expression {
471	                ChainElement::StaticMemberExpression(member) => (&member.object, member.property.name.to_string()),
472	                _ => return None,
473	            },
474	            _ => return None,
475	        };
476	        self.whole_expr(object).map(|_| key)
477	    }
478	}
