480	/// The symbols a body renders as a component tag (`<Item/>`).
481	fn tag_symbols(scoping: &Scoping, visit: impl FnOnce(&mut TagSymbols<'_>)) -> FxHashSet<SymbolId> {
482	    let mut tags = TagSymbols { scoping, symbols: FxHashSet::default() };
483	    visit(&mut tags);
484	    tags.symbols
485	}
486	
487	struct TagSymbols<'s> {
488	    scoping: &'s Scoping,
489	    symbols: FxHashSet<SymbolId>,
490	}
491	
492	impl<'a> Visit<'a> for TagSymbols<'_> {
493	    fn visit_jsx_element_name(&mut self, it: &JSXElementName<'a>) {
494	        if let JSXElementName::IdentifierReference(id) = it
495	            && let Some(symbol) =
496	                id.reference_id.get().and_then(|reference| self.scoping.get_reference(reference).symbol_id())
497	        {
498	            self.symbols.insert(symbol);
499	        }
500	    }
501	}
502	
503	/// Collects a component body's elements; those of a nested component (a function or class bound to a symbol the body
504	/// renders as a tag) go to `nested_usages`.
505	struct Elements<'r, 's, 'a> {
506	    reader: &'r Reader<'s, 'a>,
507	    tags: FxHashSet<SymbolId>,
508	    nested: u32,
509	    elements: Vec<JsxElementFact>,
510	    nested_usages: Vec<JsxUsage>,
511	}
512	
513	impl Elements<'_, '_, '_> {
514	    fn is_tag(&self, id: Option<&BindingIdentifier<'_>>) -> bool {
515	        id.and_then(|id| id.symbol_id.get()).is_some_and(|symbol| self.tags.contains(&symbol))
516	    }
517	
518	    fn in_nested(&mut self, nested: bool, walk: impl FnOnce(&mut Self)) {
519	        self.nested += u32::from(nested);
520	        walk(self);
521	        self.nested -= u32::from(nested);
522	    }
523	}
524	
525	impl<'a> Visit<'a> for Elements<'_, '_, 'a> {
526	    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
527	        let nested = matches!(&it.id, BindingPattern::BindingIdentifier(id) if self.is_tag(Some(id)))
528	            && it.init.as_ref().is_some_and(|init| {
529	                unwrap(init).is_some() || matches!(peel_expr(init), Expression::ClassExpression(_))
530	            });
531	        self.in_nested(nested, |elements| walk::walk_variable_declarator(elements, it));
532	    }
533	
534	    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
535	        let nested = it.is_declaration() && self.is_tag(it.id.as_ref());
536	        self.in_nested(nested, |elements| walk::walk_function(elements, it, flags));
537	    }
538	
539	    fn visit_class(&mut self, it: &Class<'a>) {
540	        let nested = it.is_declaration() && self.is_tag(it.id.as_ref());
541	        self.in_nested(nested, |elements| walk::walk_class(elements, it));
542	    }
543	
544	    fn visit_jsx_opening_element(&mut self, it: &JSXOpeningElement<'a>) {
545	        if self.nested > 0 {
546	            self.nested_usages.push(usage_of(it));
547	        } else {
548	            let attributes = it
549	                .attributes
550	                .iter()
551	                .map(|attribute| match attribute {
552	                    JSXAttributeItem::Attribute(attribute) => JsxAttributeFact::Named {
553	                        name: attribute_name(&attribute.name),
554	                        prop: self.reader.value_prop(attribute.value.as_ref()),
555	                    },
556	                    JSXAttributeItem::SpreadAttribute(spread) => {
557	                        JsxAttributeFact::Spread(self.reader.whole_expr(&spread.argument).unwrap_or(SpreadOf::Other))
558	                    }
559	                })
560	                .collect();
561	            self.elements.push(JsxElementFact { tag: tag_of(&it.name), attributes });
562	        }
563	        walk::walk_jsx_opening_element(self, it);
564	    }
565	}
566	
567	/// A tag as the JSX rule reads it: a lowercase first letter, a dash or a namespace makes it intrinsic.
568	fn tag_of(name: &JSXElementName<'_>) -> JsxTag {
569	    let identifier = |name: &str| {
570	        if name.starts_with(|c: char| c.is_ascii_lowercase()) || name.contains('-') {
571	            JsxTag::Intrinsic(name.to_owned())
572	        } else {
573	            JsxTag::Identifier(name.to_owned())
574	        }
575	    };
576	    match name {
577	        JSXElementName::Identifier(id) => identifier(id.name.as_str()),
578	        JSXElementName::IdentifierReference(id) => identifier(id.name.as_str()),
579	        JSXElementName::NamespacedName(namespaced) => {
580	            JsxTag::Intrinsic(format!("{}:{}", namespaced.namespace.name, namespaced.name.name))
581	        }
582	        JSXElementName::MemberExpression(member) => JsxTag::Member(member_path(member)),
583	        JSXElementName::ThisExpression(_) => JsxTag::Identifier("this".to_owned()),
584	    }
585	}
586	
587	fn member_path(member: &JSXMemberExpression<'_>) -> String {
588	    let object = match &member.object {
589	        JSXMemberExpressionObject::IdentifierReference(id) => id.name.to_string(),
590	        JSXMemberExpressionObject::MemberExpression(inner) => member_path(inner),
591	        JSXMemberExpressionObject::ThisExpression(_) => "this".to_owned(),
592	    };
593	    format!("{object}.{}", member.property.name)
594	}
595	
596	fn attribute_name(name: &JSXAttributeName<'_>) -> String {
597	    match name {
598	        JSXAttributeName::Identifier(id) => id.name.to_string(),
599	        JSXAttributeName::NamespacedName(namespaced) => {
600	            format!("{}:{}", namespaced.namespace.name, namespaced.name.name)
601	        }
602	    }
603	}
