    let b = facts(source, "B");
    assert_eq!(reads(&b), ["href"]);
    assert_eq!(b.elements, [intrinsic("a", vec![named("ref", None), named("href", Some("href"))])]);
    let m = facts(source, "M");
    assert_eq!(reads(&m), ["label"]);
    assert_eq!(m.elements, [intrinsic("span", vec![])]);
}

