           const f = () => { const { b, ...r2 } = props; return <i {...r2} /> };\n\
           return <b {...r1}>{f()}</b>\n\
         }",
        "C",
    );
    assert_eq!(facts.rests, ["r1", "r2"]);
    assert!(!facts.handed_on);
}

