);

// Byte offset (UTF-8) to UTF-16 index, per file.
const offsets = new Map();
function toUtf16(file, byte) {
  let map = offsets.get(file);
  if (!map) {
    const text = fs.readFileSync(file, 'utf8');
    map = new Map();
    let b = 0;
    for (let i = 0; i < text.length; ) {
      map.set(b, i);
      const cp = text.codePointAt(i);
      b += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
      i += cp >= 0x10000 ? 2 : 1;
    }
    map.set(b, text.length);
    offsets.set(file, map);
  }
  return map.get(byte);
}

